import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        int[] vals = new int[n];
        for (int i = 0; i < n; i++) {
            vals[i] = Integer.parseInt(st.nextToken());
        }
        int[] vals_mod = new int[n];
        for (int i = 0; i < n; i++) {
            vals_mod[i] = vals[i] % k;
        }
        if (n == 1) {
            System.out.println(vals_mod[0]);
            return;
        }
        int[] part_x = Arrays.copyOfRange(vals_mod, 0, n / 2);
        int[] part_y = Arrays.copyOfRange(vals_mod, n / 2, n);
        Set<Integer> set_x = new HashSet<>();
        Set<Integer> set_y = new HashSet<>();
        Set<Integer> temp_set_y = new HashSet<>();

        for (int v : part_x) {
            for (int prev : set_x) {
                set_y.add((prev + v) % k);
            }
            set_x.add(v);
            for (int prev : set_y) {
                set_x.add(prev);
            }
            set_y.clear();
        }

        for (int v : part_y) {
            for (int prev : set_y) {
                set_y.add((prev + v) % k);
            }
            set_y.addAll(set_x);
        }

        List<Integer> list_x = new ArrayList<>(set_x);
        List<Integer> list_y = new ArrayList<>(set_y);
        Collections.sort(list_x);
        Collections.sort(list_y);

        int max_value_found = Math.max(Collections.max(list_x), Collections.max(list_y));
        int res = max_value_found;

        for (int s_elem : list_x) {
            int target = k - 1 - s_elem;
            int idx = upperBound(list_y, target);
            if (idx > 0) {
                int r = list_y.get(idx - 1);
                int rt = list_y.get(list_y.size() - 1);
                int candidate1 = (r + s_elem) % k;
                int candidate2 = (s_elem + rt) % k;
                res = Math.max(res, Math.max(candidate1, candidate2));
            }
        }

        System.out.println(res);
    }

    private static int upperBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) <= target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}
